import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson, putJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { byUser } from '../session/session';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { PersonColumnHeaders, PersonColumns } from '../../slots/defs/personRow';
import { GRADES, isRetired, peopleKey, peoplePath, usePeople, useShowRetired } from './people';
import type { Grade, Person } from './people';
import { claimsKey } from '../claims/claims';
import type { Claim } from '../claims/claims';

// gradeFrom is the date an edit records the grade from (yyyy-mm-dd; blank for the sheet's today); a person's
// first grade applies from the beginning of time. terms are the person's own days (blank for none); contact is
// theirs, not another's on the sheet (blank for none); tags are comma separated (the server trims, lower-cases and
// drops repeats).
type Draft = { name: string; grade: Grade; gradeFrom: string; terms: string; contact: string; tags: string };
const EMPTY: Draft = { name: '', grade: 'A', gradeFrom: '', terms: '', contact: '', tags: '' };
const termsText = (p: Person) => (p.terms === null ? '' : String(p.terms));

type Quick = { name: string; amount: string };
const QUICK_EMPTY: Quick = { name: '', amount: '' };

// The quick-add bar: a name and an amount make a draft claim dated the sheet's today with an empty
// note, for the person of that name (ignoring case), who is first added with grade A when not on the
// sheet. The server checks every rule before writing, so a refusal adds no one.
function QuickAdd({ sheet, user }: { sheet: string; user: string }) {
  const queryClient = useQueryClient();
  const [draft, setDraft] = useState<Quick>(QUICK_EMPTY);

  const add = useMutation({
    mutationFn: (body: Quick) =>
      postJson<{ people: Person[]; claims: Claim[] }>(
        byUser(`/api/sheets/${encodeURIComponent(sheet)}/quick-add`, user),
        body,
      ),
    onSuccess: (updated) => {
      queryClient.setQueryData(peopleKey(sheet), updated.people);
      queryClient.setQueryData(claimsKey(sheet), updated.claims);
      setDraft(QUICK_EMPTY);
    },
  });
  const send = useSubmitOnce(add);

  const change = (next: Partial<Quick>) => {
    setDraft((d) => ({ ...d, ...next }));
    add.reset();
  };

  const submit = (e: FormEvent) => {
    e.preventDefault();
    send(draft);
  };

  return (
    <form onSubmit={submit}>
      <label>
        Quick add: name{' '}
        <input data-testid="quick-name" value={draft.name} onChange={(e) => change({ name: e.target.value })} />
      </label>{' '}
      <label>
        Amount{' '}
        <input data-testid="quick-amount" value={draft.amount} onChange={(e) => change({ amount: e.target.value })} />
      </label>{' '}
      <button type="submit" data-testid="quick-submit" disabled={add.isPending}>
        Add claim
      </button>
      {add.isError && (
        <span data-testid="quick-error" role="alert">
          {' '}
          A quick add needs a name and an amount of 0.00 or more with up to two decimals, dated outside any closed
          period.
        </span>
      )}
    </form>
  );
}

// The sheet's people: listed by position, new ones at the end (retired ones only when shown), with one form that adds a person or,
// once a person's editor is opened, edits them. The editor remembers the version of the person it loaded;
// when someone else has saved them since, the save is refused and the form shows their current values.
function People({ sheet, user }: { sheet: string; user: string }) {
  const queryClient = useQueryClient();
  const { data: everyone = [] } = usePeople(sheet);
  const [showRetired, setShowRetired] = useShowRetired();
  // Retired people have no row at all unless "show retired" is on; their claims still count in every total.
  const people = showRetired ? everyone : everyone.filter((p) => !isRetired(p));
  const [draft, setDraft] = useState<Draft>(EMPTY);
  const [editing, setEditing] = useState<{ id: number; version: number } | null>(null);

  const save = useMutation({
    mutationFn: ({ edit, body }: { edit: { id: number; version: number } | null; body: Draft }) =>
      edit === null
        ? postJson<Person[]>(byUser(peoplePath(sheet), user), body)
        : putJson<Person[]>(byUser(`${peoplePath(sheet)}/${edit.id}`, user), { ...body, version: edit.version }),
    onSuccess: (updated) => {
      queryClient.setQueryData(peopleKey(sheet), updated);
      setDraft(EMPTY);
      setEditing(null);
    },
    onError: async (error, { edit }) => {
      if (edit === null) return;
      if (!(error instanceof HttpError) || error.status !== 412) {
        // A refused edit writes nothing and closes the editor, leaving its error shown, so the form adds again.
        setDraft(EMPTY);
        setEditing(null);
        return;
      }
      // Someone else saved the person: show what is stored now, and edit from that version.
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheet) });
      const p = queryClient.getQueryData<Person[]>(peopleKey(sheet))?.find((c) => c.id === edit.id);
      if (p) {
        setDraft({ name: p.name, grade: p.grade, gradeFrom: '', terms: termsText(p), contact: p.contact ?? '', tags: p.tags.join(', ') });
        setEditing({ id: p.id, version: p.version });
      }
    },
  });
  const send = useSubmitOnce(save);

  const change = (next: Partial<Draft>) => {
    setDraft((d) => ({ ...d, ...next }));
    save.reset();
  };

  const open = (p: Person) => {
    setEditing({ id: p.id, version: p.version });
    setDraft({ name: p.name, grade: p.grade, gradeFrom: '', terms: termsText(p), contact: p.contact ?? '', tags: p.tags.join(', ') });
    save.reset();
  };

  const cancel = () => {
    setEditing(null);
    setDraft(EMPTY);
    save.reset();
  };

  const submit = (e: FormEvent) => {
    e.preventDefault();
    // The server refuses an empty name, one already on the sheet, or a save over someone else's;
    // its refusal shows as the form's error.
    send({ edit: editing, body: draft });
  };

  return (
    <section>
      <h2>People</h2>
      <form onSubmit={submit}>
        <label>
          Name{' '}
          <input data-testid="person-form-name" value={draft.name} onChange={(e) => change({ name: e.target.value })} />
        </label>{' '}
        <label>
          Grade{' '}
          <select
            data-testid="person-form-grade"
            value={draft.grade}
            onChange={(e) => change({ grade: e.target.value as Grade })}
          >
            {GRADES.map((g) => (
              <option key={g} value={g}>
                {g}
              </option>
            ))}
          </select>
        </label>{' '}
        <label>
          From{' '}
          <input
            data-testid="person-form-grade-from"
            placeholder="yyyy-mm-dd"
            value={draft.gradeFrom}
            onChange={(e) => change({ gradeFrom: e.target.value })}
          />
        </label>{' '}
        <label>
          Terms{' '}
          <input
            data-testid="person-form-terms"
            placeholder="days"
            value={draft.terms}
            onChange={(e) => change({ terms: e.target.value })}
          />
        </label>{' '}
        <label>
          Contact{' '}
          <input
            data-testid="person-form-contact"
            value={draft.contact}
            onChange={(e) => change({ contact: e.target.value })}
          />
        </label>{' '}
        <label>
          Tags{' '}
          <input
            data-testid="person-form-tags"
            placeholder="tags, comma separated"
            value={draft.tags}
            onChange={(e) => change({ tags: e.target.value })}
          />
        </label>{' '}
        <button type="submit" data-testid="person-form-submit" disabled={save.isPending}>
          {editing === null ? 'Add person' : 'Save person'}
        </button>
        {editing !== null && (
          <button type="button" data-testid="person-form-cancel" onClick={cancel}>
            Cancel
          </button>
        )}
        {save.isError && (
          <span data-testid="person-form-error" role="alert">
            {' '}
            {save.error instanceof HttpError && save.error.status === 412
              ? 'Someone else saved this person since you opened it; the form now shows their values.'
              : 'A person needs a name not already on the sheet or its tree (and, when clashing, a new name and aliases that no longer clash), a grade of A, B or C, a from-date that is a valid date or blank, terms that are a whole number of days or blank, and a contact not already another person\'s on the sheet.'}
          </span>
        )}
      </form>
      <QuickAdd sheet={sheet} user={user} />
      <label>
        <input
          type="checkbox"
          data-testid="show-retired"
          checked={showRetired}
          onChange={(e) => setShowRetired(e.target.checked || undefined)}
        />{' '}
        Show retired
      </label>
      <table>
        <thead>
          <tr>
            <th>Name</th>
            <th>Grade</th>
            <th>Terms</th>
            <th>Contact</th>
            <th>Tags</th>
            <th>Clashing</th>
            <th>From sheet</th>
            <PersonColumnHeaders.Slot sheet={sheet} user={user} />
            <th />
          </tr>
        </thead>
        <tbody>
          {people.map((p) => (
            <tr key={p.id} data-testid={`person-row-${p.id}`}>
              <td data-testid="person-name">{p.name}</td>
              <td data-testid="person-grade">{p.grade}</td>
              <td data-testid="person-terms">{termsText(p)}</td>
              <td data-testid="person-contact">{p.contact ?? ''}</td>
              <td data-testid="person-tags">{p.tags.join(', ')}</td>
              <td data-testid="person-clashing">{p.clashing ? 'yes' : 'no'}</td>
              <td data-testid="person-origin">{p.origin ?? ''}</td>
              <PersonColumns.Slot sheet={sheet} user={user} person={p} />
              <td>
                <button type="button" data-testid={`person-edit-${p.id}`} onClick={() => open(p)}>
                  Edit
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

export const contribution = SheetPanels.fill({ order: 10, Component: People });
import { useQuery } from '@tanstack/react-query';
import { useReadScope } from '../../query/live';
import { asFlag, useSearchParam } from '../../url/useSearchParam';

export type Grade = 'A' | 'B' | 'C';
export const GRADES: Grade[] = ['A', 'B', 'C'];

/** One of a person's grades, in force from its from-date (yyyy-MM-dd; null when it applies from the beginning of time). */
export type GradeFrom = { grade: Grade; from: string | null };

// grade is the one in force on the sheet's today; grades are every one recorded, by from-date.
// retiredFrom is null unless the person is retired; once set, they count as retired whatever the date.
/** One of a person's holds: from its from-date to its to-date, both included (yyyy-MM-dd; to is null when it never ends). */
export type Hold = { from: string; to: string | null };

/** One of a person's past retirements: from its retired-from date to the day they were unretired (yyyy-MM-dd). */
export type Retirement = { from: string; to: string };

// holds are every one added, in that order; their OPEN claims dated within a hold count in no live total, unless
// bound by a statement; their other claims still do.
export type Person = {
  id: number;
  name: string;
  grade: Grade;
  version: number;
  retiredFrom: string | null;
  holds: Hold[];
  grades: GradeFrom[];
  /** The person's own terms in days, ahead of their grade's and the sheet's; null when they have none. */
  terms: number | null;
  /** Whether the sheet's today is on or after retiredFrom: from then their OPEN and PENDING claims, unless bound by a
   *  statement, count in no live total. */
  retiredNow: boolean;
  /** The person's contact, trimmed and lower-cased; null when they have none. */
  contact: string | null;
  /** Whether their name or an alias is already a name or alias on another sheet of the sheet's tree (its ancestors
   *  and descendants): every edit of them is refused until it renames them out of the clash. */
  clashing: boolean;
  /** The sheet they were transferred from; null for anyone not transferred. */
  origin: string | null;
  /** Their past retirements, each ended by unretiring them, in the order they were unretired. */
  retirements: Retirement[];
  /** Their tags: each trimmed and lower-cased, repeats dropped, sorted; a claim of theirs counts in each tag's due-total. */
  tags: string[];
};

/** The person's grade in force on a date (yyyy-MM-dd): the one whose from-date is the latest on or before it. */
export function gradeOn(person: Person, date: string): Grade | undefined {
  let found: GradeFrom | undefined;
  for (const g of person.grades) {
    if (g.from !== null && g.from > date) continue;
    if (found === undefined || (found.from ?? '') < (g.from ?? '')) found = g;
  }
  return found?.grade;
}

/** Whether the person has any hold. */
export const isHeld = (p: Person) => p.holds.length > 0;

/** Whether a date (yyyy-MM-dd) is within one of the person's holds. */
export const heldOn = (p: Person, date: string) =>
  p.holds.some((h) => date >= h.from && (h.to === null || date <= h.to));

export const isRetired = (p: Person) => p.retiredFrom !== null;

/** Whether a claim of the person's dated on the day (yyyy-MM-dd), open and not bound by a statement, is kept out of
 *  every live total: it is dated within one of their holds, or their retirement date is reached. */
export const setAsideOn = (p: Person, date: string) => p.retiredNow || heldOn(p, date);

export const peopleKey = (sheet: string) => ['people', sheet] as const;

/** The mutation key every action on a person's row shares, so the row shows only its latest action's refusal. */
export const personActionKey = (sheet: string, person: number) => ['person-action', sheet, person] as const;

export const peoplePath = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}/people`;

/** Everyone on the sheet, in list order (by position; new people go to the end). */
export function usePeople(sheet: string) {
  const read = useReadScope(peopleKey(sheet));
  return useQuery({
    queryKey: read.key,
    queryFn: () => read.get<Person[]>(peoplePath(sheet)),
  });
}

/** Whether retired people are listed: off until turned on, and kept in the URL so loading a sheet leaves it be. */
export const useShowRetired = () => useSearchParam('retired', asFlag);
import { useNavigate, useSearch } from '@tanstack/react-router';

/**
 * Read and write ONE search-param key.
 *
 * State that outlives a click lives in the URL, not in a parent component — a filter, a sort, a
 * toggle, which row is selected. The control that owns a key is a self-contained file, and whoever
 * reads the key does so directly. Search params are an open namespace (declared once in
 * routes/__root.tsx), so a new key needs no schema change.
 *
 *     const [status, setStatus] = useSearchParam('status', asString);
 */
export function useSearchParam<T>(
  key: string,
  decode: (raw: unknown) => T,
): [T, (value: T | undefined) => void] {
  const search = useSearch({ strict: false }) as Record<string, unknown>;
  const navigate = useNavigate();

  const set = (value: T | undefined) => {
    void navigate({
      to: '.', // stay on the current route; only the search changes
      // Only the one key changes; every other param is left exactly as it was, so two controls
      // never clobber each other.
      search: (prev: Record<string, unknown>) => {
        const next = { ...prev };
        if (value === undefined || value === '') {
          delete next[key];
        } else {
          next[key] = value;
        }
        return next;
      },
      replace: true,
    });
  };

  return [decode(search[key]), set];
}

export const asString = (raw: unknown): string => (typeof raw === 'string' ? raw : '');
export const asNumber = (raw: unknown): number | undefined => {
  const n = Number(raw);
  return raw === undefined || raw === '' || Number.isNaN(n) ? undefined : n;
};
export const asFlag = (raw: unknown): boolean => raw === 'true' || raw === true;
